CREATE TABLE IF NOT EXISTS governance_bodies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, body_code text NOT NULL, body_name text NOT NULL, mandate text NOT NULL, quorum_rule text, voting_rule text, chair_rule text, status text NOT NULL DEFAULT 'Proposed', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS governance_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, role_code text NOT NULL, role_name text NOT NULL, authority_scope text NOT NULL, appointment_authority text, accountability_to text, can_delegate boolean NOT NULL DEFAULT false, independence_requirement text, status text NOT NULL DEFAULT 'Proposed', created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE governance_roles ADD COLUMN IF NOT EXISTS entity_name text;
ALTER TABLE governance_roles ADD COLUMN IF NOT EXISTS role_code text;
ALTER TABLE governance_roles ADD COLUMN IF NOT EXISTS appointment_authority text;
ALTER TABLE governance_roles ADD COLUMN IF NOT EXISTS can_delegate boolean NOT NULL DEFAULT false;
ALTER TABLE governance_roles ADD COLUMN IF NOT EXISTS independence_requirement text;
ALTER TABLE governance_roles ADD COLUMN IF NOT EXISTS created_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE governance_roles ALTER COLUMN layer SET DEFAULT 'Governance';
CREATE TABLE IF NOT EXISTS delegated_authority_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, rule_code text NOT NULL, decision_class text NOT NULL, authority_holder text NOT NULL, monetary_limit numeric(20,2), currency text NOT NULL DEFAULT 'NGN', approval_route text NOT NULL, dual_approval_required boolean NOT NULL DEFAULT false, cannot_delegate boolean NOT NULL DEFAULT false, evidence_required text, status text NOT NULL DEFAULT 'Proposed', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS signature_authority_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, instrument_type text NOT NULL, authority_holder text NOT NULL, signing_mode text NOT NULL, threshold_description text, second_signatory_role text, board_resolution_required boolean NOT NULL DEFAULT false, legal_review_required boolean NOT NULL DEFAULT true, status text NOT NULL DEFAULT 'Proposed', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS conflict_declarations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, person_reference text NOT NULL, role_reference text, matter_reference text, conflict_type text NOT NULL, disclosure_text text, recusal_required boolean NOT NULL DEFAULT true, mitigation_action text, resolution_status text NOT NULL DEFAULT 'Open', disclosed_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz);
CREATE TABLE IF NOT EXISTS governance_decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, decision_code text NOT NULL, matter_title text NOT NULL, decision_class text NOT NULL, originating_body text NOT NULL, requested_by text, approval_status text NOT NULL DEFAULT 'Pending', required_approvals text, evidence_reference text, conflict_check_status text NOT NULL DEFAULT 'Required', reserved_matter boolean NOT NULL DEFAULT false, legal_review_status text NOT NULL DEFAULT 'Required', decided_at timestamptz, notes text, created_at timestamptz NOT NULL DEFAULT now());
